    r = modulo.agregar_columna(df, "hp", [35, 78, 45, 160])
    assert "hp" in r.columns
    assert list(r["hp"]) == [35, 78, 45, 160]
    assert "hp" not in df.columns, "No modifiques el DataFrame original (usá .copy())"


