    os.environ["POKE_TEST_VAR"] = "rojo"
    assert modulo.leer_entorno("POKE_TEST_VAR", "azul") == "rojo"
    assert modulo.leer_entorno("NO_EXISTE_XYZ", "azul") == "azul"


